    return { cls: card.className, opacity: getComputedStyle(card).opacity, sender: document.getElementById('giftSender').textContent, name: document.getElementById('giftName').textContent, thanks: document.getElementById('giftThanks').textContent, box: { top: box.top, left: box.left, width: box.width, height: box.height } };
  })()`);
  console.log('gift:', JSON.stringify(gift));
  await capture('gift-stage');

  const invite = await evaluate(`(async () => {
    await fetch('/rpc', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ jsonrpc: '2.0', id: 4, method: 'temple.comment', params: { comment: 'PRAY', user: 'Michael R.', uniqueId: 'demo.mike.cdp' } }) });
    await new Promise((r) => setTimeout(r, 1400));
    const card = document.getElementById('prayerInvite');
    return { cls: card.className, opacity: getComputedStyle(card).opacity, title: document.getElementById('prayerInviteTitle').textContent };
  })()`);
  console.log('invite:', JSON.stringify(invite));
  await capture('prayer-invite-stage');

  console.log('console errors:', errors.length ? errors : 'none');
