  ['possible-dreams', 'Possible Dreams', 'Eugenio Mininni', 'Piano', 'Hopeful piano with soft strings', 599, 'piano'],
  ['river-flow', 'River Flow', 'Eugenio Mininni', 'Cinematic', 'Flowing cinematic ambience', 594, 'cinematic'],
  ['drawing-the-sky', 'Drawing the Sky', 'Eugenio Mininni', 'Cinematic', 'Expansive, hopeful cinematic pads', 606, 'cinematic'],
  ['moon-walk', 'Moon Walk', 'Eugenio Mininni', 'Cinematic', 'Quiet night cinematic texture', 609, 'cinematic']
];

async function download(track) {
  const [id, , , , , n, cat] = track;
  const url = `https://assets.mixkit.co/music/${n}/${n}.mp3`;
  const dest = path.join(OUT, `${id}.mp3`);
  if (fs.existsSync(dest) && fs.statSync(dest).size > 200000) {
    console.log('[skip]', id);
    return;
  }
  const res = await fetch(url, { headers: { 'User-Agent': 'Mozilla/5.0' } });
  if (!res.ok) throw new Error(`${id}: HTTP ${res.status}`);
  const buf = Buffer.from(await res.arrayBuffer());
  if (buf.length < 100000) throw new Error(`${id}: suspiciously small (${buf.length})`);
  fs.writeFileSync(dest, buf);
  console.log('[ok]', id, (buf.length / 1048576).toFixed(2), 'MB', cat);
}

(async () => {
  const queue = TRACKS.slice();
  let failed = 0;
  async function worker() {
    while (queue.length) {
      const track = queue.shift();
      try {
        await download(track);
      } catch (err) {
        failed += 1;
        console.error('[fail]', err.message);
      }
    }
  }
  await Promise.all([worker(), worker(), worker()]);
  console.log('done, failures:', failed);
  process.exit(failed ? 1 : 0);
})();
