const WS = require('ws');

const BASE = 'http://127.0.0.1:3120';
const results = [];
function check(label, ok, detail = '') {
  results.push({ label, ok, detail });
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${label}${detail ? ' — ' + detail : ''}`);
}
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function rpc(method, params = {}) {
  const res = await fetch(`${BASE}/rpc`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ jsonrpc: '2.0', id: Date.now(), method, params })
  });
  const data = await res.json();
  if (data.error) throw new Error(`${method}: ${data.error.message}`);
  return data.result;
}

(async () => {
  const adminHtml = await (await fetch(`${BASE}/admin`)).text();
  check('admin html keeps the End Live button', adminHtml.includes('id="btnFarewell"'));
  check('admin html has the library section', adminHtml.includes('Farewell Message Library') && adminHtml.includes('id="farewellLibrary"'));
  const css = await (await fetch(`${BASE}/css/admin.css`)).text();
  check('admin styles ship the library card', css.includes('.farewell-message'));

  const library = await rpc('show.farewellList');
  const messages = library?.messages || [];
  check('library lists registered messages', messages.length >= 1, `${messages.length} message(s)`);
  const base = messages.find((m) => m.id === library.default);
  check('default message is "Until We Meet Again"', base?.title === 'Until We Meet Again', base?.title);
  check('library carries four body paragraphs and a closing', base?.paragraphs?.length === 4 && base?.closing === 'God bless you. Amen.',
    `${base?.paragraphs?.length} paragraphs · closing "${base?.closing}"`);
  check('library text is the full spoken message', String(base?.text || '').endsWith('God bless you. Amen.') && String(base?.text || '').length > 380, `${base?.text?.length} chars`);

  // Unknown ids must never reach the stage.
  const bogus = await rpc('show.farewell', { messageId: 'not-a-real-message' });
  check('unknown message is rejected', bogus?.ok === false && bogus?.unknownMessage === true, bogus?.error);

  const ws = new WS('ws://127.0.0.1:3120/ws?obs=1');
  const seen = [];
  ws.on('message', (raw) => {
    try {
      const msg = JSON.parse(raw.toString('utf8'));
      seen.push({ method: msg.method, params: msg.params });
    } catch (_) {}
  });
  await new Promise((resolve, reject) => {
    ws.on('open', resolve);
    ws.on('error', reject);
    setTimeout(() => reject(new Error('ws timeout')), 8000);
  });

  let ready = false;
  for (let i = 0; i < 30; i += 1) {
    const tts = await rpc('tts.status');
    if (tts && tts.status === 'ready') { ready = true; break; }
    await sleep(2000);
  }
  check('Piper is ready', ready, ready ? 'ready' : 'not ready');

  const before = await rpc('state.get');
  const tiktokBefore = before.tiktok || {};
  const bgBefore = before.backgrounds?.current;
  const musicBefore = before.settings?.music?.volume;

  // No messageId keeps the original button behaviour: the default message.
  const first = await rpc('show.farewell');
  check('default button still plays the default message', first?.ok === true && first?.messageId === library.default, first?.messageId);
  check('returned text equals the library text', first?.text === base.text, `${first?.text?.length} chars`);
  check('cue paragraphs match the library plus closing', first?.cue?.paragraphs?.length === 5 && first.cue.paragraphs[0] === base.paragraphs[0]);

  const duplicate = await rpc('show.farewell');
  check('duplicate playback is rejected', duplicate?.ok === false && duplicate?.alreadyPlaying === true, duplicate?.error);
  const interrupt = await rpc('show.farewell', { messageId: library.default });
  check('a new request cannot interrupt an active farewell', interrupt?.ok === false && interrupt?.alreadyPlaying === true);

  await sleep(5000);
  const farewellEvents = seen.filter((m) => m.method === 'show.farewell');
  const started = farewellEvents.find((m) => m.params?.state === 'started');
  check('stage received the farewell cue', Boolean(started), `${farewellEvents.length} event(s)`);
  check('stage payload carries the selected message id and text', started?.params?.messageId === library.default && started.params.text === base.text);
  const ttsPlay = seen.find((m) => m.method === 'tts.play' && m.params?.source === 'farewell');
  check('Piper reads the exact selected text', Boolean(ttsPlay) && ttsPlay.params.text === base.text, ttsPlay ? `${ttsPlay.params.durationSec}s` : 'no tts.play');

  const after = await rpc('state.get');
  check('background unchanged', after.backgrounds?.current === bgBefore, `${bgBefore}`);
  check('music settings unchanged', after.settings?.music?.volume === musicBefore, `${musicBefore}`);
  check('TikTok connection untouched', Boolean(after.tiktok?.connected) === Boolean(tiktokBefore.connected) && after.tiktok?.username === tiktokBefore.username,
    `connected=${after.tiktok?.connected}`);
  check('show programme still running', after.settings?.show?.enabled !== false, `enabled=${after.settings?.show?.enabled}`);

  ws.close();
  const failed = results.filter((r) => !r.ok);
  console.log(`\n${results.length - failed.length}/${results.length} checks passed`);
  process.exit(failed.length === 0 ? 0 : 1);
})().catch((error) => {
  console.error('TEST ERROR', error);
  process.exit(1);
});
